28	class ToolActivitySubscription
29	{
30	public:
31	    ToolActivitySubscription() = default;
32	    ToolActivitySubscription(const ToolActivitySubscription&) = delete;
33	    ToolActivitySubscription& operator=(const ToolActivitySubscription&) = delete;
34	    ToolActivitySubscription(ToolActivitySubscription&& other) noexcept : m_unsubscribe(std::move(other.m_unsubscribe)) {}
35	    ToolActivitySubscription& operator=(ToolActivitySubscription&& other) noexcept
36	    {
37	        if (this != &other) {
38	            reset();
39	            m_unsubscribe = std::move(other.m_unsubscribe);
40	        }
41	        return *this;
42	    }
43	    ~ToolActivitySubscription() { reset(); }
44	
45	    void reset()
46	    {
47	        if (m_unsubscribe) {
48	            auto unsubscribe = std::move(m_unsubscribe);
49	            unsubscribe();
50	        }
51	    }
52	
53	    explicit operator bool() const { return static_cast<bool>(m_unsubscribe); }
54	
55	private:
56	    explicit ToolActivitySubscription(std::function<void()> unsubscribe) : m_unsubscribe(std::move(unsubscribe)) {}
57	    std::function<void()> m_unsubscribe;
58	
59	    friend class ToolExecutionCoordinator;
60	};
