69	class ToolExecutionCoordinator
70	{
71	public:
72	    // Invoked after every observable activity change with the updated record.
73	    using ActivityCallback = std::function<void(const ToolActivity&)>;
74	
75	    struct ExtensionResult
76	    {
77	        bool                     handled{false};
78	        std::string              result_json;
79	        std::optional<ToolError> error;
80	    };
81	    // Typed native extensions still execute inside this coordinator and its
82	    // approval/state machine. The host uses this for durable manufacturing
83	    // records; future MCP adapters use the same seam, never a WebView path.
84	    using ExtensionExecutor = std::function<ExtensionResult(ToolHandler, const ToolActivity&)>;
85	
86	    explicit ToolExecutionCoordinator(Workspace::IWorkspace& workspace,
87	                                      const ToolRegistry& registry = ToolRegistry::instance());
88	    ~ToolExecutionCoordinator();
89	
90	    ToolExecutionCoordinator(const ToolExecutionCoordinator&) = delete;
91	    ToolExecutionCoordinator& operator=(const ToolExecutionCoordinator&) = delete;
92	
93	    ToolActivitySubscription subscribe(ActivityCallback listener);
94	    void set_extension_executor(ExtensionExecutor executor) { m_extension_executor = std::move(executor); }
95	
96	    // The store behind the intent and plan tools. The owner holds project
97	    // storage, so it supplies this; without it those tools report the
98	    // operation unavailable rather than pretending to record anything.
99	    void set_product_state(IProductState* state) { m_product_state = state; }
100	
101	    // Action IDs default to a process-local counter; an owner with persisted
102	    // state injects its own allocator so IDs stay unique across restarts.
103	    void set_action_id_allocator(std::function<std::string()> allocator) { m_action_id_allocator = std::move(allocator); }
104	
105	    // Resolves an attachment ID to the absolute path of its stored blob. The
106	    // owner (which holds project storage) provides this so import arguments
107	    // stay opaque IDs — no machine-specific path is persisted or shown.
108	    void set_attachment_path_resolver(std::function<std::string(const std::string&)> resolver)
109	    {
110	        m_attachment_path_resolver = std::move(resolver);
111	    }
112	
113	    // Drops every record. For project replacement: the records belong to the
114	    // previous project session and any persisted history keeps its own copy.
115	    // Forgets every activity except one that is executing: a command that
116	    // replaces the project is still running while the project it was
117	    // proposed in is torn down, and it has to be able to report.
118	    void clear();
119	    const std::string& executing_action_id() const { return m_executing; }
120	    void forget_if_closed(const std::string& action_id);
121	    // Chat deletion may forget completed records, never in-flight work.
122	    void forget_terminal_activities(const std::vector<std::string>& message_ids);
123	
124	    // Creates a Pending record stamped with the current workspace session and
125	    // revision. Read-only actions are approved immediately by policy; every
126	    // other class waits for a user decision. Returns the new record.
127	    const ToolActivity& propose(const ToolRequest& request, const std::string& correlation_id,
128	                                ToolExecutionPacing pacing = {}, ToolSource source = ToolSource::Agent,
129	                                const std::string& plan_scope = {});
130	
131	    // User decisions. Each returns true only when it changed the record's
132	    // state, so a resent decision (reconnect, reload) can never run an action
133	    // twice or resurrect a terminal record.
134	    bool approve(const std::string& action_id);
135	    bool reject(const std::string& action_id);
136	    bool cancel(const std::string& action_id);
137	
138	    // Advances every Running activity by one deterministic tick: progress
139	    // first, then the native command on the final tick. The owner paces this
140	    // from a timer; tests call it directly.
141	    void pump();
142	
143	    bool any_running() const;
144	
145	    const std::vector<ToolActivity>& activities() const { return m_activities; }
146	    const ToolActivity*              find(const std::string& action_id) const;
147	
148	private:
149	    ToolActivity* find_mutable(const std::string& action_id);
150	    void          start_running(ToolActivity& activity);
151	    void          execute(ToolActivity& activity);
152	    void          fail(ToolActivity& activity, std::string code, std::string message, std::string details_json = "{}");
153	    // The ids of the regions whose geometry is still found, and, after a
154	    // change, those of them that no longer are: what a place, divide or
155	    // repair result reports as unbound.
156	    std::set<std::string> bound_regions() const;
157	    nlohmann::json        regions_unbound(const std::set<std::string>& bound_before) const;
158	    void          notify(const ToolActivity& activity);
159	    void          invalidate_pending(const Workspace::WorkspaceChanged& change);
160	
161	    struct ObserverState
162	    {
163	        std::uint64_t                             next_id{1};
164	        bool                                      alive{true};
165	        std::map<std::uint64_t, ActivityCallback> observers;
166	    };
167	
168	    Workspace::IWorkspace&           m_workspace;
169	    const ToolRegistry&               m_registry;
170	    Workspace::WorkspaceSubscription m_workspace_subscription;
171	    std::shared_ptr<ObserverState>    m_observers;
172	    IProductState*                   m_product_state{nullptr};
173	    // The slice_start call behind the run now in flight, so the slicing
174	    // section can say which handle a reader is watching.
175	    std::string                      m_slice_handle;
176	    // Whether the run m_slice_handle started has been seen, and has ended. A
177	    // later run is the person's, and activity_cancel does not stop it.
178	    bool                             m_slice_seen_running{false};
179	    bool                             m_slice_ended{false};
180	    std::string                      m_executing;
181	    ExtensionExecutor                m_extension_executor;
182	    std::function<std::string()>     m_action_id_allocator;
183	    std::function<std::string(const std::string&)> m_attachment_path_resolver;
184	    std::vector<ToolActivity>        m_activities;
185	    std::uint64_t                    m_next_action_id{1};
186	    std::uint64_t                    m_last_invalidating_revision{0};
187	    // The last change a settings patch cares about: a settings edit or a new
188	    // project. A model edit between a preview and its apply does not move it.
189	    std::uint64_t                    m_last_settings_revision{0};
190	    // slice_start calls that return when their run ends, by action id. Such a
191	    // call stays Running without holding up the others.
192	    struct SliceWait
193	    {
194	        std::optional<Workspace::PlateId>     plate;
195	        bool                                  seen_running{false};
196	        std::chrono::steady_clock::time_point started;
197	    };
198	    std::map<std::string, SliceWait> m_slice_waits;
199	    // Approved plans that a change from outside the plan reached before all
200	    // their members ran; their remaining members fail stale.
201	    std::set<std::string>            m_disturbed_plans;
202	    void finish_slice_waits();
203	};
