3	// Tool activity records and the approval policy for Agent-initiated project
4	// changes. The records carry the same semantic fields a future MCP-backed
5	// Agent must produce (tool and server identity, typed arguments, stable IDs,
6	// approval requirement, workspace session and expected revision, lifecycle
7	// state, progress, and structured result), so the coordinator, bridge, and
8	// page cannot special-case the deterministic mock. GUI-free.
9	
10	#include <cstdint>
11	#include <memory>
12	#include <optional>
13	#include <string>
14	
15	namespace Slic3r::GUI::JusPrin::Agent {
16	
17	// Lifecycle of one tool action. Pending awaits a user decision (or is
18	// auto-approved for read-only actions); Rejected, Cancelled, Succeeded, and
19	// Failed are terminal. A stale proposal fails with error code
20	// "stale_revision" rather than getting its own state.
21	enum class ToolState : std::uint8_t { Pending, Approved, Running, Succeeded, Failed, Cancelled, Rejected };
22	
23	constexpr bool tool_state_terminal(ToolState state)
24	{
25	    return state == ToolState::Succeeded || state == ToolState::Failed || state == ToolState::Cancelled ||
26	           state == ToolState::Rejected;
27	}
28	
29	// The name the page, the saved state and the tools use.
30	constexpr const char* tool_state_name(ToolState state)
31	{
32	    switch (state) {
33	    case ToolState::Pending: return "pending";
34	    case ToolState::Approved: return "approved";
35	    case ToolState::Running: return "running";
36	    case ToolState::Succeeded: return "succeeded";
37	    case ToolState::Failed: return "failed";
38	    case ToolState::Cancelled: return "cancelled";
39	    case ToolState::Rejected: return "rejected";
40	    }
41	    return "pending";
42	}
43	
44	// Approval classes from the handoff policy. ReadOnly actions do not change
45	// durable project or external state; Mutation actions durably change the
46	// project; Destructive actions revert, delete, overwrite, discard, print, or
47	// export.
48	enum class ActionClass : std::uint8_t { ReadOnly, Mutation, Destructive };
49	
50	// Assigned by the native adapter, never by untrusted tool arguments. External
51	// requests belong to the project, not to an in-app conversation message.
52	enum class ToolSource : std::uint8_t { Agent, Mcp };
53	
54	// The first production release asks for approval before every durable
55	// project mutation; read-only actions run without approval.
56	//
57	// One exemption: a mutation declared computation-only in the registry. It
58	// changes no project geometry, preset, file, printer, or durable product
59	// state; its only effect is computation, replacing a previously computed
60	// result, or recording the agent's own statement; and the person can see and
61	// reverse it in the UI. Without it every "check this print" would cost a card
62	// and the card would stop meaning anything. Destructive actions never
63	// qualify, whatever they declare.
64	constexpr bool approval_required(ActionClass action_class, bool computation_only = false)
65	{
66	    return action_class == ActionClass::Destructive ||
67	           (action_class == ActionClass::Mutation && !computation_only);
68	}
69	
70	// Destructive actions always require action-time approval and must never use
71	// a remembered approval. (No remembered approvals exist in this release; the
72	// policy still records which class may ever gain them.)
73	constexpr bool remembered_approval_allowed(ActionClass action_class)
74	{
75	    return action_class == ActionClass::Mutation;
76	}
77	
78	struct ToolError
79	{
80	    std::string code;
81	    std::string message;
82	    std::string details_json{"{}"};
83	};
84	
85	// Untrusted call data supplied by an adapter. The coordinator resolves title,
86	// action class, validation, and implementation from the registry.
87	struct ToolRequest
88	{
89	    std::string tool;
90	    std::string arguments_json; // typed arguments, serialized
91	};
92	
93	// A picture a read returns beside its structured result: PNG or JPEG,
94	// base64-encoded, at most 1280 pixels on its long edge and 2 MB. Held in
95	// memory for the adapters to project; never written to the project.
96	struct ToolImage
97	{
98	    std::string mime_type;
99	    std::string base64;
100	    int         width{0};
101	    int         height{0};
102	};
103	
104	inline constexpr int         kToolImageEdge  = 1280;
105	inline constexpr std::size_t kToolImageBytes = 2 * 1024 * 1024;
106	
107	struct ToolActivity
108	{
109	    std::string   action_id;      // coordinator-assigned, stable across reloads
110	    std::string   correlation_id; // assistant message or adapter request correlation
111	    std::string   server;
112	    std::string   tool;
113	    std::string   title;
114	    std::string   arguments_json;
115	    ActionClass   action_class{ActionClass::ReadOnly};
116	    bool          requires_approval{false};
117	    std::uint64_t session{0};           // workspace session at proposal time
118	    std::uint64_t expected_revision{0}; // workspace revision at proposal time
119	    ToolState     state{ToolState::Pending};
120	    int           progress_current{0};
121	    int           progress_total{1};
122	    std::string   result_json; // structured result when Succeeded
123	    std::shared_ptr<const ToolImage> image; // a picture beside the result, when the tool returns one
124	    // Calls sharing a plan id wait for one approval and run in the order they
125	    // were proposed; empty for a call on its own.
126	    std::string   plan_id;
127	    // Where a plan id is unique: the chat for the in-app agent, empty for MCP.
128	    // A plan is its source, scope and id together, so two clients choosing
129	    // the same id never share a card.
130	    std::string   plan_scope;
131	    std::optional<ToolError> error;
132	    ToolSource source{ToolSource::Agent};
133	};
134	
135	inline bool same_plan(const ToolActivity& lhs, const ToolActivity& rhs)
136	{
137	    return !lhs.plan_id.empty() && lhs.plan_id == rhs.plan_id && lhs.source == rhs.source && lhs.plan_scope == rhs.plan_scope;
138	}
139	
140	} // namespace Slic3r::GUI::JusPrin::Agent
