333	const ToolActivity& ToolExecutionCoordinator::propose(const ToolRequest& request, const std::string& correlation_id,
334	                                                      ToolExecutionPacing pacing, ToolSource source,
335	                                                      const std::string& plan_scope)
336	{
337	    const Workspace::WorkspaceSnapshot snapshot = m_workspace.snapshot();
338	    const ToolDefinition* definition = m_registry.find(request.tool);
339	
340	    ToolActivity activity;
341	    activity.action_id         = m_action_id_allocator ? m_action_id_allocator() : "t-" + std::to_string(m_next_action_id++);
342	    activity.correlation_id    = correlation_id;
343	    activity.source            = source;
344	    activity.server            = kServerName;
345	    activity.tool              = request.tool;
346	    activity.arguments_json    = request.arguments_json;
347	    activity.session           = snapshot.session.value();
348	    activity.expected_revision = snapshot.revision;
349	    activity.progress_total    = pacing.ticks > 0 ? pacing.ticks : 1;
350	
351	    if (definition != nullptr) {
352	        activity.title             = definition->title;
353	        activity.action_class      = definition->action_class;
354	        activity.requires_approval = m_registry.requires_approval(*definition, request.arguments_json);
355	    } else {
356	        activity.title = "Unknown tool request";
357	    }
358	
359	    m_activities.emplace_back(std::move(activity));
360	    ToolActivity& stored = m_activities.back();
361	
362	    if (definition == nullptr) {
363	        fail(stored, "unknown_tool", "This build has no tool named \"" + request.tool + "\".");
364	        return stored;
365	    }
366	
367	    ToolValidationResult validation = m_registry.validate_call(*definition, request.arguments_json);
368	    if (!validation.valid()) {
369	        fail(stored, validation.error->code, validation.error->message);
370	        return stored;
371	    }
372	    stored.arguments_json = std::move(validation.arguments_json);
373	    {
374	        const json arguments = json::parse(stored.arguments_json);
375	        stored.plan_id       = arguments.value("planId", "");
376	        stored.plan_scope    = stored.plan_id.empty() ? std::string() : plan_scope;
377	        // A plan waits for its card as a whole, including the members that
378	        // would otherwise run without one.
379	        if (!stored.plan_id.empty())
380	            stored.requires_approval = true;
381	        // A plan takes members only while its card is undecided and whole.
382	        const bool closed = std::any_of(m_activities.begin(), m_activities.end(), [&stored](const ToolActivity& member) {
383	            return member.action_id != stored.action_id && same_plan(member, stored) && member.state != ToolState::Pending;
384	        });
385	        if (!stored.plan_id.empty() && closed) {
386	            fail(stored, "plan_closed",
387	                 "Plan " + stored.plan_id + " was already decided, or one of its calls failed. Propose this with a new planId.");
388	            return stored;
389	        }
390	    }
391	    stored.title = m_registry.approval_title(*definition, stored.arguments_json);
392	
393	    if (definition->handler == ToolHandler::HistoryRestore) {
394	        const auto arguments = json::parse(stored.arguments_json);
395	        if (arguments["sessionId"] != std::to_string(snapshot.session.value())) {
396	            fail(stored, "stale_id", "That history belongs to a project that is no longer open. Read it again.");
397	            return stored;
398	        }
399	        const auto history = m_workspace.history();
400	        const auto step    = std::find_if(history.steps.begin(), history.steps.end(), [&arguments](const Workspace::HistoryStep& candidate) {
401	            return std::to_string(candidate.id) == arguments["stepId"];
402	        });
403	        if (step == history.steps.end()) {
404	            fail(stored, "stale_id", "That step is no longer in the history. Read it again.");
405	            return stored;
406	        }
407	        const std::string name = step->label.empty() ? "an unnamed step" : "\xe2\x80\x9c" + step->label + "\xe2\x80\x9d";
408	        stored.title = (arguments["point"] == "before" ? "Go back to before " : "Go to just after ") + name;
409	        if (stored.title.size() > kToolLabelLimit) stored.title.resize(kToolLabelLimit - 3), stored.title += "...";
410	    }
411	
412	    if (definition->handler == ToolHandler::ObjectImportFile) {
