766	bool ToolExecutionCoordinator::approve(const std::string& action_id)
767	{
768	    ToolActivity* activity = find_mutable(action_id);
769	    if (activity == nullptr || activity->state != ToolState::Pending)
770	        return false;
771	
772	    // The eager invalidation below normally fails a stale proposal before a
773	    // decision can arrive; the session check remains as a belt for decisions
774	    // raced against a project replacement.
775	    if (m_workspace.snapshot().session.value() != activity->session) {
776	        fail(*activity, "stale_revision", "The project changed after this action was proposed. Ask the Agent again.");
777	        return false;
778	    }
779	    if (activity->plan_id.empty()) {
780	        start_running(*activity);
781	        return true;
782	    }
783	    // One decision for the whole plan, in the order it was proposed.
784	    const ToolActivity plan = *activity;
785	    std::vector<std::string> members;
786	    for (const ToolActivity& member : m_activities)
787	        if (same_plan(member, plan) && member.state == ToolState::Pending)
788	            members.push_back(member.action_id);
789	    for (const std::string& id : members)
790	        if (ToolActivity* member = find_mutable(id); member != nullptr && member->state == ToolState::Pending)
791	            start_running(*member);
792	    return true;
793	}
