795	bool ToolExecutionCoordinator::reject(const std::string& action_id)
796	{
797	    ToolActivity* activity = find_mutable(action_id);
798	    if (activity == nullptr || activity->state != ToolState::Pending)
799	        return false;
800	    activity->state = ToolState::Rejected;
801	    notify(*activity);
802	    if (!activity->plan_id.empty()) {
803	        const ToolActivity plan = *activity;
804	        std::vector<std::string> members;
805	        for (const ToolActivity& member : m_activities)
806	            if (same_plan(member, plan) && member.state == ToolState::Pending)
807	                members.push_back(member.action_id);
808	        for (const std::string& id : members)
809	            if (ToolActivity* member = find_mutable(id); member != nullptr && member->state == ToolState::Pending) {
810	                member->state = ToolState::Rejected;
811	                notify(*member);
812	            }
813	    }
814	    return true;
815	}
